INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_111'), 1, 'Since Go 1.22 a ServeMux pattern can name a method. What does the mux answer when the path matches but the method does not?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_111'), 2, 'Write the chain out as nested calls: which wrapper runs first on the way in, and which one sees the response last on the way out?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_111'), 3, 'Look at what net/http itself does when a handler panics, and at what the client receives in that case.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_111');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_111'), 'The gateway registers only one pattern for single orders:

```go
mux.Handle("GET /v1/orders/{id}", requireToken(http.HandlerFunc(getOrder)))
```

```text
$ curl -si -X DELETE -H ''Authorization: Bearer t'' https://gw.ricerocket.vn/v1/orders/42
```

Statement: "The path matches no route for DELETE, so the mux answers `404 Not Found`."', 'single_choice'::question_type, 'False. With method patterns (Go 1.22+), a path that matches a pattern registered for other methods gets `405 Method Not Allowed` with an `Allow: GET, HEAD` header (a GET pattern also serves HEAD). 404 is only for paths no pattern matches. The misconception is that the method is part of a separate lookup; the mux reports the methods it does have for that path.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_111'), 'The access log showed nothing for requests that crashed. The chain was:

```go
handler := withRecovery(withRequestID(withLogging(log, mux)))
```

```text
$ curl -s -o /dev/null -w ''%{http_code}\n'' -H ''Authorization: Bearer t'' https://gw.ricerocket.vn/v1/boom
500
$ grep /v1/boom access.log
$
```

Statement: "The panic unwinds through withLogging before withRecovery catches it, so the log line is never written; recovery has to sit inside logging."', 'single_choice'::question_type, 'True. Each wrapper runs its code around `next.ServeHTTP`. A panic in the mux skips the rest of every wrapper between the panic and the recover, so withLogging never reaches its append. With `withRequestID(withLogging(log, withRecovery(mux)))` recovery turns the panic into a 500 first, and logging records that 500. The misconception is that wrapper order only matters for performance.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_111'), 'Before anyone added a recovery middleware, a handler with a nil-map bug produced this:

```text
# client
$ curl -s https://gw.ricerocket.vn/v1/boom
curl: (52) Empty reply from server
# gateway stderr
http: panic serving 10.8.1.4:51122: assignment to entry in nil map
goroutine 23 [running]: ...
```

Statement: "net/http recovers the panic for that one request so the process keeps serving others, but the client gets no HTTP response; a recovery middleware is what turns it into a proper 500 that clients and metrics can see."', 'single_choice'::question_type, 'True. The server recovers a handler panic per request, logs the stack and closes the connection, so other requests are fine but this client sees an empty reply instead of a status code. A recovery middleware answers 500 (when nothing has been written yet), so the client, the load balancer and the access log all see the error. The misconception is that one panic takes the whole server down, or that net/http answers 500 by itself.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_111') AND order_index = 3)
    RETURNING id
)
