-- challenge chal_coding_gcn_112 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gcn_112', (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gcn-1-1' AND is_deleted = false LIMIT 1), 'gateway-routes-middleware', 'Wire the gateway''s routes and middleware', 'The editor holds `main.go` of Rice Rocket''s API gateway with key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that: `GET /healthz` answers `ok` without a token; `GET /v1/orders/{id}` and `POST /v1/orders` need a bearer token and a wrong method gets 405 with an `Allow` header; the order handler reads the id from the matched pattern; every request carries an `X-Request-ID` (the load balancer''s, or a new one); and every request, including a panicking one, leaves one access-log line with its real status. The file ends with a small copy of the net/http API (same names, without the `http.` prefix) so Run compiles in a second; Run sends test requests through the handler and prints the responses and the log.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
