INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_112'), 1, 'Trace one request through the chain: which wrapper must see the final status, and which one must turn a panic into a status before that?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_112'), 2, 'Look at method patterns like `"GET /path/{name}"`, `r.PathValue`, a wrapper type that overrides `WriteHeader`, and the order of nested `with...(...)` calls.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_112'), 3, 'A courier webhook service with the same shape: `mux.Handle("POST /hooks/{provider}", verifySignature(h))`, `provider := r.PathValue("provider")`, and `return withTrace(withMetrics(withRecovery(mux)))` so metrics count the 500s that recovery produces.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_112'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"routes","label":"Routes: method + path patterns; probes need no token","code":"mux.HandleFunc(\"GET /healthz\", func(w ResponseWriter, r *Request) {\n\tfmt.Fprint(w, \"ok\")\n})\nmux.Handle(\"GET /v1/orders/{id}\", requireToken(HandlerFunc(getOrder)))\nmux.Handle(\"POST /v1/orders\", requireToken(HandlerFunc(createOrder)))\nmux.Handle(\"GET /v1/boom\", requireToken(HandlerFunc(boom)))"},{"id":"chain-order","label":"Wrap the mux: request id, then logging, then recovery","code":"return withRequestID(withLogging(log, withRecovery(mux)))"},{"id":"path-value","label":"Read the order id the pattern matched","code":"id := r.PathValue(\"id\")"},{"id":"log-status","label":"Serve through a recorder; 200 if WriteHeader is never called","code":"rec := &statusRecorder{ResponseWriter: w, status: StatusOK}\nnext.ServeHTTP(rec, r)"},{"id":"chain-recovery-outside","label":"Wrap the mux: request id, then logging, then recovery","code":"return withRecovery(withRequestID(withLogging(log, mux)))","distractor":true},{"id":"log-status-zero","label":"Serve through a recorder; 200 if WriteHeader is never called","code":"rec := &statusRecorder{ResponseWriter: w}\nnext.ServeHTTP(rec, r)","distractor":true},{"id":"routes-any-method","label":"Routes: method + path patterns; probes need no token","code":"mux.HandleFunc(\"/healthz\", func(w ResponseWriter, r *Request) {\n\tfmt.Fprint(w, \"ok\")\n})\nmux.Handle(\"/v1/orders/{id}\", requireToken(HandlerFunc(getOrder)))\nmux.Handle(\"/v1/orders\", requireToken(HandlerFunc(createOrder)))\nmux.Handle(\"/v1/boom\", requireToken(HandlerFunc(boom)))","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_112');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_112'), 'Probes reach /healthz without a token; an order is read by its id', '{"requests":[{"method":"GET","path":"/healthz"},{"method":"GET","path":"/v1/orders/42","headers":{"Authorization":"Bearer t-courier-7"}}]}', '{"responses":[{"status":200,"allow":"","requestId":"rid-1","body":"ok"},{"status":200,"allow":"","requestId":"rid-2","body":"{\"order\":\"42\"}"}],"log":["rid-1 GET /healthz 200","rid-2 GET /v1/orders/42 200"]}', 6, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_112'), 'A wrong method gets 405 with Allow; a missing token gets 401', '{"requests":[{"method":"DELETE","path":"/v1/orders/42","headers":{"Authorization":"Bearer t-courier-7"}},{"method":"GET","path":"/v1/orders/42"}]}', '{"responses":[{"status":405,"allow":"GET, HEAD","requestId":"rid-1","body":"Method Not Allowed"},{"status":401,"allow":"","requestId":"rid-2","body":"missing bearer token"}],"log":["rid-1 DELETE /v1/orders/42 405","rid-2 GET /v1/orders/42 401"]}', 6, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_112'), 'A panicking upstream handler answers 500 and still shows up in the access log', '{"requests":[{"method":"GET","path":"/v1/boom","headers":{"Authorization":"Bearer t-courier-7"}},{"method":"GET","path":"/healthz"}]}', '{"responses":[{"status":500,"allow":"","requestId":"rid-1","body":"internal error"},{"status":200,"allow":"","requestId":"rid-2","body":"ok"}],"log":["rid-1 GET /v1/boom 500","rid-2 GET /healthz 200"]}', 6, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_112'), 'The load balancer''s request id is kept; requests without one get a fresh id', '{"requests":[{"method":"GET","path":"/v1/orders/7","headers":{"Authorization":"Bearer t","X-Request-ID":"lb-7f3a"}},{"method":"GET","path":"/healthz"},{"method":"GET","path":"/healthz"}]}', '{"responses":[{"status":200,"allow":"","requestId":"lb-7f3a","body":"{\"order\":\"7\"}"},{"status":200,"allow":"","requestId":"rid-1","body":"ok"},{"status":200,"allow":"","requestId":"rid-2","body":"ok"}],"log":["lb-7f3a GET /v1/orders/7 200","rid-1 GET /healthz 200","rid-2 GET /healthz 200"]}', 6, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_112'), '201 is logged as 201; an empty id is 404; PUT on the collection is 405 Allow POST', '{"requests":[{"method":"POST","path":"/v1/orders","headers":{"Authorization":"Bearer t-courier-7"}},{"method":"GET","path":"/v1/orders/","headers":{"Authorization":"Bearer t-courier-7"}},{"method":"PUT","path":"/v1/orders","headers":{"Authorization":"Bearer t-courier-7"}}]}', '{"responses":[{"status":201,"allow":"","requestId":"rid-1","body":"{\"order\":\"new\"}"},{"status":404,"allow":"","requestId":"rid-2","body":"404 page not found"},{"status":405,"allow":"POST","requestId":"rid-3","body":"Method Not Allowed"}],"log":["rid-1 POST /v1/orders 201","rid-2 GET /v1/orders/ 404","rid-3 PUT /v1/orders 405"]}', 6, false, true, 5);
