VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_121'), 1, 'A token bucket refills over time but has a size. What happens to tokens that would overflow it?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_121'), 2, 'Who writes each entry of X-Forwarded-For? The client can send the header too, and proxies append to it.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_121'), 3, 'Each gateway pod keeps its own buckets in memory. How many pods can a client''s requests land on?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_121');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_121'), 'The restaurant partner API is limited to `rate = 5` tokens per second with `burst = 10`. A partner''s batch job sleeps overnight, then starts:

```text
02:00:00  last request
07:00:00  job starts, sends 2,000 requests as fast as it can
```

Statement: "After 5 idle hours the bucket holds 90,000 tokens, so the first 2,000 requests all pass at once."', 'single_choice'::question_type, 'False. A token bucket never holds more than its burst: refill is `min(burst, tokens + elapsed x rate)`. After any idle time the job gets 10 requests at once, then 5 per second. That cap is what makes the burst a safety limit; without it an idle client could flatten the api. The misconception is that a limiter banks unused capacity.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_121') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_121'), 'Requests come through the cloud load balancer (10.0.0.0/8), which appends the address it saw. The limiter keyed anonymous clients like this:

```go
hops := strings.Split(r.Header.Get("X-Forwarded-For"), ",")
key := strings.TrimSpace(hops[0])
```

```text
X-Forwarded-For: 1.1.1.1, 203.0.113.66
X-Forwarded-For: 2.2.2.2, 203.0.113.66
X-Forwarded-For: 3.3.3.3, 203.0.113.66
```

Statement: "The leftmost entry is safe to use here, because the load balancer is the one that sets X-Forwarded-For."', 'single_choice'::question_type, 'False. The load balancer appends to whatever the client sent, so everything left of the last entry is client-controlled. A scraper that sends a new fake address each time gets a fresh bucket each time, as in the log (the real address 203.0.113.66 is the last entry). Trust X-Forwarded-For only when the peer is your load balancer, and take the entry it added (the rightmost, with one proxy layer).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_121') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_121'), 'The gateway runs 4 replicas behind the load balancer, each with an in-memory limiter of 10 requests per second per API key. A partner reports:

```text
partner key rest-12: sent 38 req/s for a minute, received 38 x 200, 0 x 429
```

Statement: "Each pod counts only the requests it receives, so with requests spread over 4 pods a client can get up to about 4 times the configured rate; divide the limit by the replica count or keep the buckets in a shared store like Redis."', 'single_choice'::question_type, 'True. In-memory buckets are per process. Spread over 4 pods, 38 req/s is about 9.5 per pod, under each pod''s limit of 10. Either set the per-pod limit to limit / replicas (simple, but uneven with sticky clients and wrong while the HPA changes the count), or move the counters to a shared store (Redis with an atomic script) when the limit matters. The misconception is that a per-process limiter enforces a global limit.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_121') AND order_index = 3)
    RETURNING id
)
