-- challenge chal_coding_gcn_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gcn_122', (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gcn-1-2' AND is_deleted = false LIMIT 1), 'per-client-token-bucket', 'Limit each client with a token bucket', 'The editor holds the gateway''s limiter (`main.go`) with key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that: each client has a bucket of `burst` tokens refilled at `rate` tokens per second and never above `burst`; a request spends a token or is refused with a wait until the next token; `Retry-After` is that wait in whole seconds rounded up; anonymous clients are keyed by their own address, taking X-Forwarded-For only when the peer is the load balancer (10.0.0.0/8) and then only its last entry; and `Evict` forgets buckets that are full again. Run plays timed requests through the limiter and prints each decision.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
