-- challenge chal_coding_gcn_132 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gcn_132', (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gcn-1-3' AND is_deleted = false LIMIT 1), 'order-validation-problem-details', 'Fix the order validation', 'Last month''s gateway check for `POST /v1/orders` refused the iOS app''s orders (it sends `application/json; charset=utf-8`), silently dropped a misspelled field, and reported only the first invalid field, so the app showed one error at a time. The editor holds the check (`main.go`) with the faulty blocks missing, each marked by a `// [ ]` line; some pieces are the original buggy blocks. Fill every line so that: JSON with any parameters is accepted and anything else gets 415; unknown fields and broken JSON get 400; every invalid field is listed in one 422; and refusals use the `application/problem+json` media type. Run checks test bodies and prints the status, the media type and the problem or the parsed order.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
