-- challenge chal_coding_gcn_142 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gcn_142', (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gcn-2-1' AND is_deleted = false LIMIT 1), 'consistent-hash-ring', 'Route restaurants with a consistent hash ring', 'The gateway sends each restaurant''s requests to one courier-matcher instance, which keeps that restaurant''s prep-time model in memory. The first router used `hash(restaurant) % instances`: scaling from 4 to 5 instances sent most restaurants to a cold instance and the database took the load. The editor holds the hash ring (`main.go`) with key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that: each instance gets `vnodes` points on the ring (the file''s `hash` of `<instance>#<i>`), kept sorted; `Remove` takes an instance''s points off; and `Get` returns the owner of the first point at or after the key''s hash, skipping instances that are down and wrapping past the end of the ring. Run assigns 10,000 restaurants before and after a change (add, remove, down) and counts how many moved.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
