INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_142'), 1, 'Picture the ring as a sorted list of numbers: which point owns a key whose hash is larger than every point, and what must happen to the list after you append new points?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_142'), 2, 'Look at `sort.Search` (it returns the first index where the condition holds, or len when none does), `sort.Slice`, the modulo of an index by the number of points, and filtering a slice in place.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_142'), 3, 'A cache-shard router with the same shape: 100 points per Redis shard from `fnv(shard + "#" + i)`, `i := sort.Search(len(points), func(j int) bool { return points[j] >= fnv(key) })`, then `for n := 0; n < len(points); n++ { s := owner[points[(i+n)%len(points)]]; if healthy[s] { return s } }`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_142'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"add-points","label":"One point per virtual node, then keep the points sorted","code":"for i := 0; i < r.vnodes; i++ {\n\tp := hash(upstream + \"#\" + strconv.Itoa(i))\n\tr.points = append(r.points, p)\n\tr.owner[p] = upstream\n}\nsort.Slice(r.points, func(a, b int) bool { return r.points[a] < r.points[b] })"},{"id":"remove-points","label":"Drop every point the upstream owns","code":"kept := r.points[:0]\nfor _, p := range r.points {\n\tif r.owner[p] == upstream {\n\t\tdelete(r.owner, p)\n\t} else {\n\t\tkept = append(kept, p)\n\t}\n}\nr.points = kept"},{"id":"first-point","label":"Find the first point at or after the key''s hash","code":"i := sort.Search(len(r.points), func(j int) bool { return r.points[j] >= h })"},{"id":"walk-clockwise","label":"Walk clockwise past upstreams that are down, wrapping around","code":"for n := 0; n < len(r.points); n++ {\n\tif u := r.owner[r.points[(i+n)%len(r.points)]]; !down[u] {\n\t\treturn u\n\t}\n}\nreturn \"\""},{"id":"add-points-one-per-upstream","label":"One point per virtual node, then keep the points sorted","code":"p := hash(upstream)\nr.points = append(r.points, p)\nr.owner[p] = upstream\nsort.Slice(r.points, func(a, b int) bool { return r.points[a] < r.points[b] })","distractor":true},{"id":"first-point-modulo","label":"Find the first point at or after the key''s hash","code":"i := int(h % uint64(len(r.points)))","distractor":true},{"id":"walk-no-wrap","label":"Walk clockwise past upstreams that are down, wrapping around","code":"for n := i; n < len(r.points); n++ {\n\tif u := r.owner[r.points[n]]; !down[u] {\n\t\treturn u\n\t}\n}\nreturn \"\"","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
