-- challenge chal_quiz_gcn_151 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_gcn_151', (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gcn-2-2' AND is_deleted = false LIMIT 1), 'health-circuit-breaking-quiz', 'Read the hung menu instance', 'Three statements about the afternoon one menu-service instance hung and the gateway kept sending it traffic. Decide whether each one is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
