INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_151'), 1, 'Compare what a client waits for with the breaker closed (the full timeout) and open (no upstream call at all). What else does a waiting request hold in the gateway?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_151'), 2, 'Ask what a 404 says about the menu service''s health. Who could send many 404s in a row, and what would happen to every other client if they opened the breaker?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_151'), 3, 'Work out the worst case of the active check: how often it probes, and how many failed probes it needs before the instance leaves the pool.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_151');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_151'), 'The gateway''s metrics for the menu route while instance `menu-2` hung, before and after the breaker opened:

```text
# breaker closed
menu_requests{status="504"}  1,240 / min   p99 2.00 s   gateway goroutines 3,900
# breaker open (after 3 timeouts in a row)
menu_requests{status="503"}  1,180 / min   p99 0.001 s  gateway goroutines 410
```

Statement: "Failing fast with 503 does not fix the menu, but it stops clients waiting 2 s each and frees the goroutines and connections those waits held, while the menu service gets room to recover."', 'single_choice'::question_type, 'True. With the breaker closed every request to the hung instance waits for the full 2 s timeout, holding a goroutine, a client connection and an upstream connection; at 1,240 requests a minute they pile up (3,900 goroutines). Open, the gateway answers at once without calling the upstream, so the waits and the load on the struggling service both disappear. The misconception is that a breaker is about the error rate; it is about not spending resources on calls that will fail.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_151') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_151'), 'A partner integration requested dish ids that do not exist for a few minutes:

```text
14:02:11 GET /menu/rr-118/dishes/99901  upstream=menu-1 status=404 1.8 ms
14:02:11 GET /menu/rr-118/dishes/99902  upstream=menu-1 status=404 1.7 ms
14:02:11 GET /menu/rr-118/dishes/99903  upstream=menu-1 status=404 1.9 ms
14:02:11 breaker menu-1: closed -> open
14:02:12 GET /menu/rr-007/dishes/12      status=503 (breaker open)
```

Statement: "Counting the 404s as failures is right: they are error responses, so the breaker protected the menu service."', 'single_choice'::question_type, 'False. A 404 means the menu service worked and answered correctly that the dish does not exist. Counting client errors as failures lets one misbehaving client open the breaker for everyone: the next customer''s valid request got 503. Breakers count what says the upstream is unhealthy: timeouts, connection errors and 5xx (Resilience4j and Envoy''s outlier detection make the same distinction by configuration). The misconception is that every non-2xx status means the upstream is broken.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_151') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_151'), 'The gateway''s active health check for each menu instance:

```yaml
healthCheck:
  path: /healthz
  interval: 5s
  timeout: 1s
  unhealthyThreshold: 3   # failed probes in a row before the instance leaves the pool
  healthyThreshold: 2
```

Statement: "An instance that hangs right after a passing probe keeps receiving real traffic for about 15 seconds before this check removes it, so a breaker that reacts to failures of real requests is still needed."', 'single_choice'::question_type, 'True. The check needs 3 failed probes 5 seconds apart (each failing after its 1 s timeout), so a hang just after a good probe is noticed after roughly 15 seconds, and every real request routed there in the meantime waits for its own timeout. Passive signals (a breaker per upstream, outlier detection) react to the real traffic within a few failed requests. The two complement each other: active checks bring an instance back, passive ones take it out fast. The misconception is that a health endpoint alone protects users.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_151') AND order_index = 3)
    RETURNING id
)
