-- challenge chal_coding_gcn_152 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gcn_152', (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gcn-2-2' AND is_deleted = false LIMIT 1), 'menu-circuit-breaker', 'Put a circuit breaker in front of the menu service', 'When one menu-service instance hung, the gateway sent it every request and each one waited for the 2 s timeout. The editor holds `breaker.go` with its key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that: a call longer than `TimeoutMs` is cut and the client gets 504, an upstream 5xx becomes 502, and any other status (4xx included) passes through; only timeouts and 5xx count as failures; `FailureThreshold` failures in a row open the breaker, and a success in between resets the count; while open, requests get 503 at once without calling the upstream until `OpenForMs` has passed; then requests go through as trials (half-open): one failure opens it again for a new cool-down, `SuccessThreshold` successes in a row close it. Run replays request timelines against the program.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
