INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_152'), 1, 'Draw the three states and the arrows between them, then ask for each arrow: which function moves it (allow or record) and at what time (arrival or end of the call)?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_152'), 2, 'Look at `allow` for the open state (cool-down, then half-open), at `record` for half-open (failure reopens, successes close) and for closed (count in a row, reset on success), and at how `serve` turns a call into a status and a failure flag.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_152'), 3, 'A login throttle with the same shape: `if s.state == "locked" { if now-s.lockedAt < s.cfg.LockForMs { return false }; s.state = "trial" }` in allow, and in record `if s.state == "trial" { if failed { s.lock(now); return }; s.state = "open"; return }`, `if !failed { s.fails = 0; return }; s.fails++; if s.fails >= s.cfg.MaxFails { s.lock(now) }`.');
