tb.successes = 0\n\t\treturn\n\t}\n\tb.successes++\n\tif b.successes >= b.cfg.SuccessThreshold {\n\t\tb.moveTo(\"closed\", now)\n\t\tb.failures = 0\n\t}\n\treturn\n}","distractor":true}]'::jsonb)
