INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gcn_162', (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gcn-2-3' AND is_deleted = false LIMIT 1), 'menu-cache-singleflight', 'Cache the menus without a stampede', 'The gateway cached each restaurant''s menu for 60 s. When the entry for a popular restaurant expired at lunch, hundreds of requests missed at once and all called the menu service, which fell over; failed calls were cached too, so customers saw an empty menu for a minute. The editor holds `menucache.go` with its key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that `Get`: returns an entry younger than `ttlMs` without calling the menu service; makes concurrent misses for the same key share one call and all receive its result; never caches a failed call; and serves the expired entry when a refresh fails (stale-if-error). Run sends bursts of concurrent requests and counts the calls the menu service gets.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
