VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_162'), 1, 'Follow two goroutines that miss at the same moment: which one calls the menu service, where does the other wait, and what must happen to the shared call once it is finished so the next expiry starts a new one?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_162'), 2, 'Look at the TTL check in the fresh-hit block, the `inflight` map (join an existing call, wait on `done`), what is written to `entries` on success and on failure, and the order of storing the result, removing the call and closing `done`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_162'), 3, 'A token cache with the same shape: `if t, ok := c.tokens[user]; ok && c.now() < t.expires { return t.value, nil }`, `if f, ok := c.pending[user]; ok { c.mu.Unlock(); <-f.ready; return f.token, f.err }`, and after the login call `if err == nil { c.tokens[user] = token{...} }; f.token, f.err = tok, err; delete(c.pending, user); close(f.ready)`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_162'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"fresh-hit","label":"Serve a fresh entry without calling the menu service","code":"if e, ok := c.entries[key]; ok && c.now()-e.fetchedAt < c.ttlMs {\n\tc.mu.Unlock()\n\treturn e.value, nil\n}"},{"id":"join-inflight","label":"Wait for a call already on its way and use its result","code":"if cl, ok := c.inflight[key]; ok {\n\tc.mu.Unlock()\n\t<-cl.done\n\treturn cl.value, cl.err\n}"},{"id":"store-result","label":"Keep a success, fall back to the stale entry on a failure","code":"if err == nil {\n\tc.entries[key] = entry{value: value, fetchedAt: c.now()}\n} else if e, ok := c.entries[key]; ok {\n\tvalue, err = e.value, nil\n}"},{"id":"finish-call","label":"Hand the result to the waiters and forget the finished call","code":"cl.value, cl.err = value, err\ndelete(c.inflight, key)\nclose(cl.done)"},{"id":"finish-call-keep-inflight","label":"Hand the result to the waiters and forget the finished call","code":"cl.value, cl.err = value, err\nclose(cl.done)","distractor":true},{"id":"fresh-hit-forever","label":"Serve a fresh entry without calling the menu service","code":"if e, ok := c.entries[key]; ok {\n\tc.mu.Unlock()\n\treturn e.value, nil\n}","distractor":true},{"id":"store-result-cache-errors","label":"Keep a success, fall back to the stale entry on a failure","code":"c.entries[key] = entry{value: value, fetchedAt: c.now()}","distractor":true}]'::jsonb)
