INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_gcn_171', (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gcn-3-1' AND is_deleted = false LIMIT 1), 'graceful-shutdown-quiz', 'Read the 502s of every rollout', 'Three statements about the burst of 502s the ingress logged each time the gateway was rolled out. Decide whether each one is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
