VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_171'), 1, 'Read the documentation of `http.Server.Shutdown` and `http.Server.Close` side by side: what happens to a request that is half-way through its handler in each case?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_171'), 2, 'SIGTERM and the removal from the Service''s endpoints are both triggered by the pod being deleted. Is one of them guaranteed to happen before the other, everywhere in the cluster?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_171'), 3, 'Look up what the kubelet does when `terminationGracePeriodSeconds` runs out and the process is still alive.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_171');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_171'), 'The gateway''s first shutdown handler:

```go
sig := make(chan os.Signal, 1)
signal.Notify(sig, syscall.SIGTERM)
<-sig
ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
defer cancel()
srv.Shutdown(ctx)
```

Statement: "`srv.Shutdown` closes every open connection at once, like `srv.Close`, so requests in flight at that moment fail; the 20-second context only limits how long closing takes."', 'single_choice'::question_type, 'False. `Shutdown` first closes the listeners (no new connections), then closes idle connections and waits for active ones to become idle, that is, for the requests in flight to finish; the context bounds that wait, and when it expires `Shutdown` returns its error so you can decide what to do next. `Close` is the one that cuts active connections at once. (Hijacked connections such as WebSockets are not tracked; `RegisterOnShutdown` is how you tell them to finish.) The misconception is that a graceful shutdown means closing faster.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_171') AND order_index = 1)
    RETURNING id
)
