INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gcn_172', (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-cloud-native') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gcn-3-1' AND is_deleted = false LIMIT 1), 'gateway-graceful-shutdown', 'Shut the gateway down without dropping requests', 'Every rollout of the gateway produced a burst of 502s, and once a stuck request kept a pod alive until SIGKILL, losing the last logs and a half-processed job. The editor holds `shutdown.go`, the SIGTERM handler, with its key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that the gateway: keeps serving for `DrainDelayMs` while the load balancers stop sending traffic; then stops accepting and waits for the requests in flight, but only for the time left in the grace period after the drain delay, the worker stop and a safety margin; stops the background workers and flushes the logs; and exits 0 when every request finished or 1 when one had to be cut. Run replays rollouts against a simulated pod with a virtual clock.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
