WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_181'), 'The checkout dashboard and the histogram behind it, for the same hour:

```text
avg(gateway_request_seconds{route="/checkout"})          0.121 s
histogram_quantile(0.50, ...{route="/checkout"})       0.064 s
histogram_quantile(0.99, ...{route="/checkout"})       3.000 s
gateway_request_seconds_bucket{route="/checkout",le="2"}    9 800
gateway_request_seconds_bucket{route="/checkout",le="4"}   10 000
```

Statement: "About 2% of checkouts take between 2 and 4 seconds: the average hides them, and the p99 from the histogram shows them."', 'single_choice'::question_type, 'True. 10,000 - 9,800 = 200 of 10,000 requests (2%) fall between 2 s and 4 s. The average (0.121 s) blends them with 9,800 fast ones and looks healthy; p50 says the typical request is fast; p99 says one checkout in fifty waits about 3 s, which is what customers complained about. Percentiles from histograms are estimates (interpolated inside a bucket), so bucket bounds should sit near the latencies you care about. The misconception is that a low average means nobody is slow.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gcn_181') AND order_index = 1)
    RETURNING id
)
