VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_182'), 1, 'Work one small example by hand: five values, the cumulative count per `le`, then where rank 2.5 falls and how far into that bucket it is.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_182'), 2, 'Look at the search that picks a bucket (`>=` or `>`), the loop that adds bucket counts until it reaches the rank, the interpolation between the bucket''s lower and upper bound, and how a path segment is recognised as an id.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_182'), 3, 'A size histogram with the same shape: `i := sort.SearchFloat64s(h.limits, kb)`; for the median, `rank := 0.5 * float64(h.n)`, walk the buckets summing counts until `>= rank`, then `lo + (hi-lo)*(rank-before)/float64(h.counts[i])`; for labels, `strings.Split(p, "/")` and replace segments that `strconv.ParseUint` accepts.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gcn_182'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"bucket-index","label":"Pick the bucket: the first upper bound >= the value","code":"i := sort.SearchFloat64s(h.Bounds, v)"},{"id":"quantile-rank","label":"Find the rank and the bucket that holds it","code":"rank := q * float64(h.Total)\nvar below uint64\ni := 0\nfor ; i < len(h.Counts); i++ {\n\tif float64(below+h.Counts[i]) >= rank {\n\t\tbreak\n\t}\n\tbelow += h.Counts[i]\n}"},{"id":"interpolate","label":"Interpolate inside the bucket like histogram_quantile","code":"if i >= len(h.Bounds) {\n\treturn h.Bounds[len(h.Bounds)-1]\n}\nlower := 0.0\nif i > 0 {\n\tlower = h.Bounds[i-1]\n}\nupper := h.Bounds[i]\nreturn lower + (upper-lower)*(rank-float64(below))/float64(h.Counts[i])"},{"id":"route-template","label":"Replace numeric ids in the path with {id}","code":"parts := strings.Split(path, \"/\")\nfor i, p := range parts {\n\tif _, err := strconv.ParseUint(p, 10, 64); err == nil {\n\t\tparts[i] = \"{id}\"\n\t}\n}\nreturn strings.Join(parts, \"/\")"},{"id":"bucket-index-exclusive","label":"Pick the bucket: the first upper bound >= the value","code":"i := sort.Search(len(h.Bounds), func(k int) bool { return h.Bounds[k] > v })","distractor":true},{"id":"interpolate-upper-bound","label":"Interpolate inside the bucket like histogram_quantile","code":"if i >= len(h.Bounds) {\n\treturn h.Bounds[len(h.Bounds)-1]\n}\nreturn h.Bounds[i]","distractor":true},{"id":"route-template-raw-path","label":"Replace numeric ids in the path with {id}","code":"return strings.TrimSuffix(path, \"/\")","distractor":true}]'::jsonb)
